class ExponentialRippleValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Global quadratic trend (ensures convexity at large distances)
        base = x ** 2

        # Exponential envelope that decays with distance from origin
        envelope = np.exp(-np.abs(x) / 2.5)

        # High-frequency oscillation with distance-dependent amplitude
        oscillation = 0.25 * envelope * np.sin(9 * np.pi * x) ** 2

        # Sum over all dimensions (separable)
        return np.sum(base + oscillation)

