    def f(self, x):
        # Base function with tanh modulation creating variable curvature
        base = x**2 * (1 + np.tanh(0.5 * x**2))

        # Multi-frequency oscillations with position-dependent amplitude
        oscillation = 2 * np.sin(3 * x) + 1.5 * np.cos(5 * x)

        # Amplitude modulation that decreases with distance
