class RationalPowerOscillation:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Rational power base term
        rational_base = np.sum(x**2 / (1 + x**2))

        # Dimension-specific oscillatory perturbations
        oscillatory = np.zeros_like(x)
        for i in range(self.dim):
            # Frequency increases with dimension index
            freq = 2 + 0.5 * i
            # Amplitude decreases with dimension index
            amp = 5 - 0.5 * i
            oscillatory[i] = amp * np.sin(freq * x[i])

        return rational_base + np.sum(oscillatory)
